import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        BigDecimal bestPrice = null;
        int bestGrams = 1;

        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            BigDecimal price = new BigDecimal(st.nextToken());
            int grams = Integer.parseInt(st.nextToken());

            if (bestPrice == null
                    || price.multiply(BigDecimal.valueOf(bestGrams))
                            .compareTo(bestPrice.multiply(BigDecimal.valueOf(grams))) < 0) {
                bestPrice = price;
                bestGrams = grams;
            }
        }

        BigDecimal cost = bestPrice.multiply(BigDecimal.valueOf(1000))
                .divide(BigDecimal.valueOf(bestGrams), 2, RoundingMode.HALF_UP);

        System.out.println(cost.toPlainString());
    }
}
